import { randomUUID } from 'node:crypto';
import { Inject, Injectable } from '@nestjs/common';
import { invariant } from '../../../../packages/platform/src/errors.js';
import { digest } from '../../../../packages/platform/src/security.js';
import type { OrderEvent, OrderStatus } from '../../../../packages/contracts/src/events.js';
import { Money, OrderAggregate, Stock } from '../domain/order.js';
import {
  ORDER_STORE,
  snapshot,
  type OrderStore,
  type StoredOrder,
  type StoredItem,
} from './order-store.js';
import type { ActorContext, CreateOrder } from './commands.js';

@Injectable()
export class OrdersService {
  constructor(@Inject(ORDER_STORE) private readonly store: OrderStore) {}
  async create(input: CreateOrder, key: string, context: ActorContext) {
    const { actor, correlationId } = context;
    invariant(
      actor.role !== 'WAREHOUSE',
      'FORBIDDEN',
      'No tienes permiso para crear pedidos.',
      403,
    );
    invariant(
      actor.role !== 'CUSTOMER' || actor.customerId === input.customerId,
      'FORBIDDEN',
      'Solo puedes crear pedidos para tu cuenta.',
      403,
    );
    const quantities = new Map<string, number>();
    for (const item of input.items)
      quantities.set(item.productId, (quantities.get(item.productId) ?? 0) + item.quantity);
    invariant(
      [...quantities.values()].every((q) => q <= 10_000),
      'INVALID_QUANTITY',
      'La cantidad acumulada supera el límite.',
      422,
    );
    const itemsInput = [...quantities]
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([productId, quantity]) => ({ productId, quantity }));
    const requestHash = digest(JSON.stringify({ ...input, items: itemsInput }));
    return this.store.transaction(async (tx) => {
      const prior = await tx.lockRequest(actor.sub, key);
      if (prior) {
        invariant(
          prior.requestHash === requestHash,
          'IDEMPOTENCY_CONFLICT',
          'Esta clave ya se utilizó con otros datos.',
        );
        const order = await tx.order(prior.orderId);
        invariant(order, 'ORDER_NOT_FOUND', 'Pedido no encontrado.', 404);
        return snapshot(order, await tx.items(order.id));
      }
      const customer = await tx.customer(input.customerId);
      invariant(customer, 'CUSTOMER_NOT_FOUND', 'Cliente no encontrado.', 404);
      const products = await tx.products(itemsInput.map((i) => i.productId));
      invariant(
        products.length === itemsInput.length,
        'PRODUCT_NOT_FOUND',
        'Uno o más productos no existen.',
        404,
      );
      const now = new Date();
      const orderId = randomUUID();
      let total = Money.of(0);
      const items: StoredItem[] = [];
      for (const item of itemsInput) {
        const product = products.find((p) => p.id === item.productId)!;
        invariant(product.active, 'PRODUCT_INACTIVE', `El producto ${product.sku} está inactivo.`);
        const stock = new Stock(product.stock, product.reserved).reserve(item.quantity);
        product.reserved = stock.reserved;
        product.updatedAt = now;
        tx.saveProduct(product);
        total = total.add(Money.of(product.priceCents).times(item.quantity));
        items.push({
          id: randomUUID(),
          orderId,
          productId: product.id,
          sku: product.sku,
          name: product.name,
          quantity: item.quantity,
          unitPriceCents: product.priceCents,
        });
      }
      const number = `NX-${now.getUTCFullYear()}-${await tx.nextNumber()}`;
      const order: StoredOrder = {
        id: orderId,
        number,
        customerId: customer.id,
        customerName: customer.name,
        deliveryAddress: input.deliveryAddress,
        status: 'CONFIRMED',
        totalCents: total.cents,
        currency: 'PEN',
        version: 1,
        notes: input.notes,
        createdBy: actor.sub,
        createdAt: now,
        updatedAt: now,
      };
      await tx.insertOrder(order, items);
      for (const item of items)
        tx.movement(item.productId, order.id, 'RESERVE', item.quantity, actor.sub);
      tx.history(order.id, 'CONFIRMED', 'Pedido registrado y existencias reservadas.', actor);
      tx.audit('ORDER_CREATED', order.id, actor, correlationId);
      const view = snapshot(order, items);
      tx.event({
        id: randomUUID(),
        schemaVersion: 1,
        type: 'OrderConfirmed',
        occurredAt: now.toISOString(),
        correlationId,
        data: view,
      });
      tx.remember(actor.sub, key, requestHash, order.id);
      return view;
    });
  }
  async transition(
    id: string,
    input: { status: OrderStatus; expectedVersion: number; note: string },
    context: ActorContext,
  ) {
    const { actor, correlationId } = context;
    const allowed = input.status === 'CANCELLED' ? ['ADMIN', 'SALES'] : ['ADMIN', 'WAREHOUSE'];
    invariant(
      allowed.includes(actor.role),
      'FORBIDDEN',
      'No tienes permiso para este cambio de estado.',
      403,
    );
    return this.store.transaction(async (tx) => {
      const order = await tx.order(id, true);
      invariant(order, 'ORDER_NOT_FOUND', 'Pedido no encontrado.', 404);
      const next = new OrderAggregate(order.status, order.version).transition(
        input.status,
        input.expectedVersion,
      );
      const items = await tx.items(id);
      if (next.inventoryEffect !== 'NONE') {
        const products = await tx.products(items.map((i) => i.productId));
        for (const item of items) {
          const product = products.find((p) => p.id === item.productId)!;
          const current = new Stock(product.stock, product.reserved);
          const stock =
            next.inventoryEffect === 'RELEASE'
              ? current.release(item.quantity)
              : current.dispatch(item.quantity);
          product.stock = stock.onHand;
          product.reserved = stock.reserved;
          product.updatedAt = new Date();
          tx.saveProduct(product);
          tx.movement(product.id, id, next.inventoryEffect, item.quantity, actor.sub);
        }
      }
      order.status = next.status;
      order.version = next.version;
      order.updatedAt = new Date();
      tx.saveOrder(order);
      tx.history(id, order.status, input.note, actor);
      tx.audit(`ORDER_${order.status}`, id, actor, correlationId);
      const eventTypes: Record<OrderStatus, OrderEvent['type']> = {
        CONFIRMED: 'OrderConfirmed',
        PREPARING: 'OrderPreparing',
        DISPATCHED: 'OrderDispatched',
        DELIVERED: 'OrderDelivered',
        CANCELLED: 'OrderCancelled',
      };
      const view = snapshot(order, items);
      tx.event({
        id: randomUUID(),
        schemaVersion: 1,
        type: eventTypes[order.status],
        occurredAt: order.updatedAt.toISOString(),
        correlationId,
        data: view,
      });
      return view;
    });
  }
  list(input: Parameters<OrderStore['list']>[0], context: ActorContext) {
    return this.store.list({
      ...input,
      ...(context.actor.role === 'CUSTOMER' ? { customerId: context.actor.customerId! } : {}),
    });
  }
  async detail(id: string, context: ActorContext) {
    const order = await this.store.detail(
      id,
      context.actor.role === 'CUSTOMER' ? context.actor.customerId! : undefined,
    );
    invariant(order, 'ORDER_NOT_FOUND', 'Pedido no encontrado.', 404);
    return order;
  }
}

import { invariant } from '../../../../packages/platform/src/errors.js';
import type { OrderStatus } from '../../../../packages/contracts/src/events.js';

export class Money {
  private constructor(
    readonly cents: number,
    readonly currency: 'PEN' = 'PEN',
  ) {}
  static of(cents: number): Money {
    invariant(
      Number.isSafeInteger(cents) && cents >= 0 && cents <= 2_000_000_000,
      'INVALID_AMOUNT',
      'El importe está fuera del rango permitido.',
      422,
    );
    return new Money(cents);
  }
  times(quantity: number): Money {
    return Money.of(this.cents * quantity);
  }
  add(other: Money): Money {
    return Money.of(this.cents + other.cents);
  }
}
export class Stock {
  constructor(
    readonly onHand: number,
    readonly reserved: number,
  ) {
    invariant(
      Number.isSafeInteger(onHand) &&
        onHand <= 2_000_000_000 &&
        Number.isSafeInteger(reserved) &&
        onHand >= 0 &&
        reserved >= 0 &&
        reserved <= onHand,
      'INVALID_STOCK',
      'El stock debe cubrir las unidades reservadas.',
      422,
    );
  }
  get available() {
    return this.onHand - this.reserved;
  }
  reserve(quantity: number): Stock {
    this.quantity(quantity);
    invariant(
      quantity <= this.available,
      'INSUFFICIENT_STOCK',
      `Solo hay ${this.available} unidades disponibles.`,
    );
    return new Stock(this.onHand, this.reserved + quantity);
  }
  release(quantity: number): Stock {
    this.quantity(quantity);
    invariant(quantity <= this.reserved, 'INVALID_RESERVATION', 'La reserva no es válida.');
    return new Stock(this.onHand, this.reserved - quantity);
  }
  dispatch(quantity: number): Stock {
    this.quantity(quantity);
    invariant(quantity <= this.reserved, 'INVALID_RESERVATION', 'La reserva no es válida.');
    return new Stock(this.onHand - quantity, this.reserved - quantity);
  }
  adjust(delta: number): Stock {
    invariant(
      Number.isSafeInteger(delta) && delta !== 0,
      'INVALID_ADJUSTMENT',
      'El ajuste debe ser un entero distinto de cero.',
      422,
    );
    return new Stock(this.onHand + delta, this.reserved);
  }
  private quantity(value: number) {
    invariant(
      Number.isSafeInteger(value) && value > 0,
      'INVALID_QUANTITY',
      'La cantidad debe ser un entero mayor que cero.',
      422,
    );
  }
}
const transitions: Record<OrderStatus, readonly OrderStatus[]> = {
  CONFIRMED: ['PREPARING', 'CANCELLED'],
  PREPARING: ['DISPATCHED', 'CANCELLED'],
  DISPATCHED: ['DELIVERED'],
  DELIVERED: [],
  CANCELLED: [],
};
export class OrderAggregate {
  constructor(
    readonly status: OrderStatus,
    readonly version: number,
  ) {}
  transition(next: OrderStatus, expectedVersion: number) {
    invariant(
      expectedVersion === this.version,
      'STALE_ORDER',
      'El pedido cambió. Actualiza la vista antes de continuar.',
    );
    invariant(
      transitions[this.status].includes(next),
      'INVALID_TRANSITION',
      'Este cambio de estado no está permitido.',
    );
    return {
      status: next,
      version: this.version + 1,
      inventoryEffect:
        next === 'CANCELLED' ? 'RELEASE' : next === 'DISPATCHED' ? 'DISPATCH' : 'NONE',
    } as const;
  }
}

import { Inject, Injectable } from '@nestjs/common';
import { LockMode, type FilterQuery } from '@mikro-orm/core';
import { DATABASE, outbox, type Database } from '../../../../packages/platform/src/persistence.js';
import type { OrderStore, OrderTransaction, OrderView } from '../application/order-store.js';
import { snapshot } from '../application/order-store.js';
import {
  ProductRecord,
  CustomerRecord,
  OrderRecord,
  OrderItemRecord,
  OrderHistoryRecord,
  StockMovementRecord,
  AuditRecord,
  IdempotencyRecord,
} from './entities.js';
@Injectable()
export class MikroOrderStore implements OrderStore {
  constructor(@Inject(DATABASE) private readonly db: Database) {}
  async transaction<T>(work: (tx: OrderTransaction) => Promise<T>): Promise<T> {
    return this.db.em.fork().transactional(async (em) => {
      const tx: OrderTransaction = {
        nextNumber: async () => {
          const [row] = await em.execute<{ value: string }[]>(
            "select nextval('order_number_seq') as value",
          );
          return String(row!.value).padStart(6, '0');
        },
        lockRequest: async (actorId, key) => {
          await em.execute('select pg_advisory_xact_lock(hashtextextended(?, 0))', [
            `${actorId}:${key}`,
          ]);
          return em.findOne(IdempotencyRecord, { actorId, key });
        },
        customer: (id) => em.findOne(CustomerRecord, { id }),
        products: (ids) =>
          em.find(
            ProductRecord,
            { id: { $in: ids } },
            { orderBy: { id: 'asc' }, lockMode: LockMode.PESSIMISTIC_WRITE },
          ),
        order: (id, lock) =>
          em.findOne(OrderRecord, { id }, lock ? { lockMode: LockMode.PESSIMISTIC_WRITE } : {}),
        items: (orderId) => em.find(OrderItemRecord, { orderId }, { orderBy: { sku: 'asc' } }),
        saveProduct: (product) => {
          em.persist(product);
        },
        insertOrder: async (order, items) => {
          em.persist(Object.assign(new OrderRecord(), order));
          await em.flush();
          em.persist(items.map((item) => Object.assign(new OrderItemRecord(), item)));
        },
        saveOrder: (order) => {
          em.persist(order);
        },
        history: (orderId, status, note, actor) => {
          em.persist(
            Object.assign(new OrderHistoryRecord(), {
              orderId,
              status,
              note,
              actorId: actor.sub,
              actorName: actor.name,
            }),
          );
        },
        movement: (productId, orderId, kind, quantity, actorId) => {
          em.persist(
            Object.assign(new StockMovementRecord(), {
              productId,
              orderId,
              kind,
              quantity,
              reason: kind,
              actorId,
            }),
          );
        },
        audit: (action, resourceId, actor, correlationId) => {
          em.persist(
            Object.assign(new AuditRecord(), {
              action,
              resourceId,
              actorId: actor.sub,
              actorName: actor.name,
              correlationId,
            }),
          );
        },
        event: (event) => {
          em.persist(outbox(event));
        },
        remember: (actorId, key, requestHash, orderId) => {
          em.persist(
            Object.assign(new IdempotencyRecord(), { actorId, key, requestHash, orderId }),
          );
        },
      };
      return work(tx);
    });
  }
  async list(input: Parameters<OrderStore['list']>[0]) {
    const em = this.db.em.fork();
    const where: FilterQuery<OrderRecord> = {
      ...(input.customerId ? { customerId: input.customerId } : {}),
      ...(input.status ? { status: input.status } : {}),
      ...(input.search
        ? {
            $or: [
              { number: { $ilike: `%${input.search}%` } },
              { customerName: { $ilike: `%${input.search}%` } },
            ],
          }
        : {}),
    };
    const [orders, total] = await em.findAndCount(OrderRecord, where, {
      limit: input.pageSize,
      offset: (input.page - 1) * input.pageSize,
      orderBy: { createdAt: 'desc', id: 'desc' },
    });
    const items = orders.length
      ? await em.find(
          OrderItemRecord,
          { orderId: { $in: orders.map((o) => o.id) } },
          { orderBy: { sku: 'asc' } },
        )
      : [];
    return {
      data: orders.map((o) =>
        snapshot(
          o,
          items.filter((i) => i.orderId === o.id),
        ),
      ),
      total,
      page: input.page,
      pageSize: input.pageSize,
    };
  }
  async detail(id: string, customerId?: string): Promise<OrderView | null> {
    const em = this.db.em.fork();
    const order = await em.findOne(OrderRecord, { id, ...(customerId ? { customerId } : {}) });
    if (!order) return null;
    const [items, history] = await Promise.all([
      em.find(OrderItemRecord, { orderId: id }, { orderBy: { sku: 'asc' } }),
      em.find(OrderHistoryRecord, { orderId: id }, { orderBy: { createdAt: 'asc' } }),
    ]);
    return {
      ...snapshot(order, items),
      history: history.map(({ id, status, note, actorName, createdAt }) => ({
        id,
        status,
        note,
        actorName,
        createdAt,
      })),
    };
  }
}

import { createHash, randomBytes, scrypt, timingSafeEqual } from 'node:crypto';
import { promisify } from 'node:util';
const derive = promisify(scrypt);
export async function hashPassword(password: string): Promise<string> {
  const salt = randomBytes(16).toString('hex');
  const key = (await derive(password, salt, 64)) as Buffer;
  return `${salt}:${key.toString('hex')}`;
}
export async function verifyPassword(password: string, encoded: string): Promise<boolean> {
  const [salt, hex] = encoded.split(':');
  if (!salt || !hex) return false;
  const expected = Buffer.from(hex, 'hex');
  const actual = (await derive(password, salt, 64)) as Buffer;
  return expected.length === actual.length && timingSafeEqual(expected, actual);
}
export function digest(value: string) {
  return createHash('sha256').update(value).digest('hex');
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Money, Stock, OrderAggregate } from '../../apps/operations/src/domain/order.js';
import { BusinessError } from '../../packages/platform/src/errors.js';
import { hashPassword, verifyPassword } from '../../packages/platform/src/security.js';
import { integrationEventSchema } from '../../packages/contracts/src/events.js';

test('una reserva reduce lo disponible y mantiene las unidades físicas', () => {
  const stock = new Stock(8, 0).reserve(3);
  assert.equal(stock.onHand, 8);
  assert.equal(stock.available, 5);
});
test('el stock cero impide nuevas ventas', () => {
  assert.throws(() => new Stock(0, 0).reserve(1), { code: 'INSUFFICIENT_STOCK' });
});
test('la última unidad no puede reservarse dos veces', () => {
  const stock = new Stock(1, 0).reserve(1);
  assert.throws(() => stock.reserve(1), { code: 'INSUFFICIENT_STOCK' });
});
test('cancelar libera la reserva sin aumentar las existencias físicas', () => {
  const stock = new Stock(8, 5).release(3);
  assert.equal(stock.onHand, 8);
  assert.equal(stock.available, 6);
});
test('despachar descuenta tanto stock físico como reserva', () => {
  const stock = new Stock(8, 5).dispatch(3);
  assert.equal(stock.onHand, 5);
  assert.equal(stock.reserved, 2);
  assert.equal(stock.available, 3);
});
test('un ajuste no puede consumir unidades ya reservadas', () => {
  assert.throws(() => new Stock(8, 5).adjust(-4), { code: 'INVALID_STOCK' });
});
test('una liberación no puede superar la reserva', () => {
  assert.throws(() => new Stock(8, 2).release(3), { code: 'INVALID_RESERVATION' });
});
test('las cantidades fraccionarias no son válidas para unidades', () => {
  assert.throws(() => new Stock(8, 0).reserve(1.5), { code: 'INVALID_QUANTITY' });
  assert.throws(() => new Stock(2_000_000_000, 0).adjust(1), { code: 'INVALID_STOCK' });
});
test('las reservas nunca superan el stock en una secuencia de movimientos', () => {
  let stock = new Stock(100, 0);
  for (let i = 0; i < 20; i++) stock = stock.reserve(3);
  for (let i = 0; i < 10; i++) stock = stock.dispatch(2);
  for (let i = 0; i < 10; i++) stock = stock.release(4);
  assert.equal(stock.onHand, 80);
  assert.equal(stock.reserved, 0);
});
test('el dinero usa céntimos enteros y suma sin errores decimales', () => {
  assert.equal(Money.of(10).add(Money.of(20)).cents, 30);
  assert.equal(Money.of(1290).times(3).cents, 3870);
});
test('los importes fuera de rango se rechazan antes de llegar a SQL', () => {
  assert.throws(() => Money.of(2_000_000_000).times(2), BusinessError);
  assert.throws(() => Money.of(1.5), BusinessError);
});
test('el flujo del pedido avanza con versiones consecutivas', () => {
  const result = new OrderAggregate('CONFIRMED', 1).transition('PREPARING', 1);
  assert.deepEqual(result, { status: 'PREPARING', version: 2, inventoryEffect: 'NONE' });
});
test('los cambios con una versión antigua se rechazan', () => {
  assert.throws(() => new OrderAggregate('PREPARING', 2).transition('DISPATCHED', 1), {
    code: 'STALE_ORDER',
  });
});
test('despachar activa el descuento de inventario', () => {
  assert.equal(
    new OrderAggregate('PREPARING', 2).transition('DISPATCHED', 2).inventoryEffect,
    'DISPATCH',
  );
});
test('cancelar activa la liberación de inventario', () => {
  assert.equal(
    new OrderAggregate('PREPARING', 2).transition('CANCELLED', 2).inventoryEffect,
    'RELEASE',
  );
});
test('un pedido entregado es terminal', () => {
  assert.throws(() => new OrderAggregate('DELIVERED', 4).transition('CANCELLED', 4), {
    code: 'INVALID_TRANSITION',
  });
});
test('no se permite saltar la preparación para despachar', () => {
  assert.throws(() => new OrderAggregate('CONFIRMED', 1).transition('DISPATCHED', 1), {
    code: 'INVALID_TRANSITION',
  });
});
test('las contraseñas usan sales distintas y se verifican sin almacenar texto plano', async () => {
  const a = await hashPassword('una-contraseña-larga');
  const b = await hashPassword('una-contraseña-larga');
  assert.notEqual(a, b);
  assert.equal(await verifyPassword('una-contraseña-larga', a), true);
  assert.equal(await verifyPassword('otra-contraseña', a), false);
});
test('un evento con versión desconocida no pasa el contrato', () => {
  assert.equal(
    integrationEventSchema.safeParse({ schemaVersion: 2, type: 'OrderConfirmed' }).success,
    false,
  );
});

package com.boroughledger.crm.customers;

import com.boroughledger.crm.audit.AuditLog;
import com.boroughledger.crm.audit.AuditRepository;
import com.boroughledger.crm.users.AppUser;
import java.util.UUID;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Sort;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class CustomerService {
    private final CustomerRepository customers;
    private final AuditRepository audit;
    public CustomerService(CustomerRepository customers, AuditRepository audit) {
        this.customers = customers; this.audit = audit;
    }
    @Transactional(readOnly = true)
    public Page<CustomerDto.Response> list(AppUser actor, int page, int size, String search) {
        PageRequest request = PageRequest.of(page, Math.min(size, 50), Sort.by("createdAt").descending());
        return customers.search(actor.getOrganizationId(), search == null || search.isBlank() ? null : search.strip(), request)
                .map(CustomerDto.Response::from);
    }
    @Transactional(readOnly = true)
    public CustomerDto.Response get(AppUser actor, UUID id) { return CustomerDto.Response.from(find(actor, id)); }
    @Transactional
    public CustomerDto.Response create(AppUser actor, CustomerDto.Request input) {
        Customer c = customers.save(new Customer(actor.getOrganizationId(), input.name(), input.email(), input.phone(), input.industry()));
        audit.save(new AuditLog(actor.getOrganizationId(), actor.getId(), "CREATED", "CUSTOMER", c.getId()));
        return CustomerDto.Response.from(c);
    }
    @Transactional
    public CustomerDto.Response update(AppUser actor, UUID id, CustomerDto.Request input) {
        Customer c = find(actor, id);
        c.update(input.name(), input.email(), input.phone(), input.industry());
        audit.save(new AuditLog(actor.getOrganizationId(), actor.getId(), "UPDATED", "CUSTOMER", c.getId()));
        return CustomerDto.Response.from(c);
    }
    @Transactional
    public void archive(AppUser actor, UUID id) {
        Customer c = find(actor, id);
        c.archive();
        audit.save(new AuditLog(actor.getOrganizationId(), actor.getId(), "ARCHIVED", "CUSTOMER", c.getId()));
    }
    private Customer find(AppUser actor, UUID id) {
        // Tenant isolation at query level; foreign organization is indistinguishable from a nonexistent customer.
        return customers.findByIdAndOrganizationIdAndArchivedAtIsNull(id, actor.getOrganizationId())
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Cliente no encontrado"));
    }
}

package com.boroughledger.crm.customers;

import java.util.Optional;
import java.util.UUID;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;

public interface CustomerRepository extends JpaRepository<Customer, UUID> {
    @org.springframework.data.jpa.repository.Query("select c from Customer c where c.organizationId=:org and c.archivedAt is null and (:search is null or lower(c.name) like lower(concat('%',:search,'%')) or lower(c.email) like lower(concat('%',:search,'%')))")
